@props([
    'name' => null,
    'value' => null,
    'max' => 5,
    'invalid' => false,
    'disabled' => false,
    'size' => null,
])

@aware([
    'fieldInvalid' => false,
    'controlId' => null,
])

@php
    if (! filled($name)) {
        throw new \InvalidArgumentException('The rating component requires a [name] attribute.');
    }

    $invalid = $invalid || $fieldInvalid;
    $maxStars = max(1, min(10, (int) $max));
    $currentValue = filled($value) ? max(0, min($maxStars, (int) $value)) : 0;

    $resolvedControlId = $attributes->get('id')
        ?? $controlId
        ?? $name;

    $rootClasses = collect([
        'rating flex min-w-0 items-center gap-1',
        'w-full' => ! filled($attributes->get('class')),
    ])->filter()->implode(' ');

    $rootAttributes = $attributes
        ->except(['name', 'value', 'max', 'invalid', 'disabled', 'size', 'id'])
        ->class($rootClasses)
        ->merge([
            'id' => $resolvedControlId,
            'data-rating' => true,
            'data-rating-max' => $maxStars,
            'role' => 'radiogroup',
            'aria-label' => __('stencil-ui::messages.rating_label'),
        ]);

    if ($disabled) {
        $rootAttributes = $rootAttributes->merge(['data-disabled' => 'true']);
    }

    if ($invalid) {
        $rootAttributes = $rootAttributes->merge([
            'data-invalid' => 'true',
            'aria-invalid' => 'true',
        ]);
    }

    $starSize = $size === 'sm' ? 'size-5' : 'size-6';
@endphp

<div {{ $rootAttributes }}>
    <input type="hidden" name="{{ $name }}" value="{{ $currentValue }}" data-rating-hidden-input />

    <div class="rating__stars flex items-center gap-0.5" data-rating-stars>
        @for ($i = 1; $i <= $maxStars; $i++)
            @php
                $isChecked = $i === $currentValue;
                $isTabStop = $isChecked || ($currentValue === 0 && $i === 1);
            @endphp
            <button
                type="button"
                class="rating__star inline-flex items-center justify-center rounded-sm text-zinc-500 transition-colors hover:text-amber-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10 dark:text-zinc-400 dark:hover:text-amber-400 dark:focus-visible:ring-zinc-300/20 {{ $starSize }} {{ $i <= $currentValue ? '!text-amber-700 dark:!text-amber-400' : '' }}"
                data-rating-star
                data-rating-value="{{ $i }}"
                role="radio"
                aria-checked="{{ $isChecked ? 'true' : 'false' }}"
                aria-label="{{ __('stencil-ui::messages.rating_star', ['value' => $i]) }}"
                tabindex="{{ $isTabStop ? '0' : '-1' }}"
                @if ($disabled) disabled @endif
            >
                <x-ui::icon name="star" class="{{ $starSize }}" data-rating-star-icon />
            </button>
        @endfor
    </div>
</div>

/**
 * Stencil — star rating input (vanilla JS, no Alpine).
 */

const RATING_SELECTOR = '[data-rating]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initRatings(root = document) {
    root.querySelectorAll(RATING_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindRating(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindRating(root) {
    /** @type {HTMLInputElement | null} */
    const hiddenInput = root.querySelector('[data-rating-hidden-input]');
    const stars = Array.from(root.querySelectorAll('[data-rating-star]')).filter(
        (node) => node instanceof HTMLButtonElement,
    );
    const max = Number.parseInt(root.getAttribute('data-rating-max') ?? '5', 10);
    const disabled = root.hasAttribute('data-disabled');

    if (!(hiddenInput instanceof HTMLInputElement) || stars.length === 0) {
        return;
    }

    /**
     * @param {HTMLElement} target
     */
    function dispatchChange(target) {
        target.dispatchEvent(new Event('input', { bubbles: true }));
        target.dispatchEvent(new Event('change', { bubbles: true }));
    }

    /**
     * @param {number} value
     * @param {{ focus?: boolean }} [options]
     */
    function setValue(value, options = {}) {
        const clamped = Math.max(0, Math.min(max, value));
        hiddenInput.value = String(clamped);

        stars.forEach((star) => {
            const starValue = Number.parseInt(star.getAttribute('data-rating-value') ?? '0', 10);
            const active = starValue <= clamped;
            const checked = starValue === clamped;

            star.classList.toggle('!text-amber-700', active);
            star.classList.toggle('dark:!text-amber-400', active);
            star.setAttribute('aria-checked', checked ? 'true' : 'false');

            const isTabStop = checked || (clamped === 0 && starValue === 1);
            star.tabIndex = isTabStop ? 0 : -1;

            if (options.focus && isTabStop) {
                star.focus();
            }
        });

        dispatchChange(hiddenInput);
    }

    stars.forEach((star) => {
        star.addEventListener('click', (event) => {
            event.preventDefault();

            if (disabled) {
                return;
            }

            const value = Number.parseInt(star.getAttribute('data-rating-value') ?? '0', 10);
            const current = Number.parseInt(hiddenInput.value || '0', 10);

            if (current === value) {
                setValue(0, { focus: true });
            } else {
                setValue(value, { focus: true });
            }
        });

        star.addEventListener('keydown', (event) => {
            if (disabled) {
                return;
            }

            const current = Number.parseInt(hiddenInput.value || '0', 10);
            const starValue = Number.parseInt(star.getAttribute('data-rating-value') ?? '0', 10);

            switch (event.key) {
                case 'ArrowRight':
                case 'ArrowUp':
                    event.preventDefault();
                    setValue(Math.min(max, (current || starValue) + 1), { focus: true });
                    break;
                case 'ArrowLeft':
                case 'ArrowDown':
                    event.preventDefault();
                    setValue(Math.max(1, (current || starValue) - 1), { focus: true });
                    break;
                case 'Home':
                    event.preventDefault();
                    setValue(1, { focus: true });
                    break;
                case 'End':
                    event.preventDefault();
                    setValue(max, { focus: true });
                    break;
                case ' ':
                case 'Enter':
                    event.preventDefault();
                    if (current === starValue) {
                        setValue(0, { focus: true });
                    } else {
                        setValue(starValue, { focus: true });
                    }
                    break;
                default:
                    break;
            }
        });
    });
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initRatings(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initRatings());
    } else {
        initRatings();
    }
}
